        discount: "Free Shipping",
        name: "Apple Accessories",
        image: productImage,
        link: "https://apple.com",
        storeName: "Apple",
        cashbackRate: "2% Cash Back",
        expiryDate: "Dec 25, 2023",
        isHot: false,
        terms: "On orders over $50. US shipping addresses only."
