      {
        id: 7,
        discount: "25% Off",
        name: "Samsung Galaxy Phones",
        image: productImage,
        link: "https://samsung.com",
        storeName: "Samsung",
        cashbackRate: "6% Cash Back",
        expiryDate: "Jan 10, 2024",
        isHot: true,
