      {
        id: 8,
        discount: "Buy 2 Get 1 Free",
        name: "Adidas Footwear",
        image: productImage,
        link: "https://adidas.com",
        storeName: "Adidas",
        cashbackRate: "5% Cash Back",
        expiryDate: "Nov 30, 2023",
        isHot: false,
        terms: "Selected styles only. Lowest priced item is free."
